pub fn retention_days(locale: Locale, days: i64) -> String {
    let values = &[("days", days.to_string())];
    match locale {
        Locale::En => {
            let template = match Some(days) {
                Some(1) => "1 day",
                _ => match plural_category(days) {
                    "other" => "{days} days",
                    _ => "{days} days",
                },
            };
            plural(template, days, values)
        }
        Locale::Zh => fill("{days} 天", values),
    }
}

