pub fn history_storage_usage(locale: Locale, count: i64, mib: &str) -> String {
    let values = &[("count", count.to_string()), ("mib", mib.to_string())];
    match locale {
        Locale::En => {
            let template = match Some(count) {
                Some(1) => "1 entry · {mib} MiB stored",
                _ => match plural_category(count) {
                    "other" => "{count} entries",
                    _ => "{count} entries · {mib} MiB stored",
                },
            };
            plural(template, count, values)
        }
        Locale::Zh => fill("已保存 {count} 条 · {mib} MiB", values),
    }
}

